using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Collections.Generic;
namespace Ara {public static class SharedEngineTests {
 static void Yes(bool b,string why){if(!b)throw new Exception(why);}
 public static void Run(Action<string,Action> check,string dir){
  object[] fixtures;using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("Aiary.EngineFixtures.json"))using(var reader=new StreamReader(stream,Encoding.UTF8))fixtures=(object[])JsonMap.Codec().DeserializeObject(reader.ReadToEnd());
  foreach(var item in fixtures){var c=JsonMap.Map(item);check("shared engine: original C# parity "+JsonMap.Str(c,"name"),()=>{var s=SharedEngine.Read<State>(c["state"]);var d=s.GetDay(PhoneCodec.Date(JsonMap.Str(c,"date")));var expected=JsonMap.Child(c,"expected");GridPlan p;try{p=GridEngine.Build(s,d);}catch(InvalidOperationException){if(expected.ContainsKey("error"))return;throw;}Yes(!expected.ContainsKey("error"),"previously invalid input accepted");var blocks=JsonMap.Items(expected,"blocks");Yes(blocks.Length==p.DisplayBlocks.Count,"block count");for(int i=0;i<blocks.Length;i++){var a=JsonMap.Map(blocks[i]);var b=p.DisplayBlocks[i];Yes(b.Id==JsonMap.Str(a,"id")&&b.Start==d.Wake.Date.AddMinutes(Convert.ToInt32(a["start"]))&&b.Count==Convert.ToInt32(a["count"])&&b.MealId==JsonMap.Str(a,"meal"),"block "+i);}Yes(p.Overflow==Convert.ToInt32(expected["overflow"])&&p.Saved==Convert.ToInt32(expected["saved"])&&Adaptive.Target(s,d)==d.Wake.Date.AddMinutes(Convert.ToInt32(expected["sleep"])),"buffer and bedtime");});}
  check("shared engine: embedded core identity and restart",()=>{string expected;using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("Aiary.Engine.js"))using(var memory=new MemoryStream()){stream.CopyTo(memory);expected=PhoneCodec.Hash(memory.ToArray());}Yes(SharedEngine.Identity==expected,"same embedded bytes");var s=State.New();var d=s.GetDay(new DateTime(2026,10,22));string first=SharedEngine.Json(GridEngine.Build(s,d));SharedEngine.Stop();Yes(SharedEngine.Json(GridEngine.Build(s,d))==first,"restart changes no result");});
  check("shared engine: rejected request does not poison transport",()=>{bool rejected=false;try{SharedEngine.Call("unsupported-request");}catch(InvalidOperationException){rejected=true;}Yes(rejected&&SharedEngine.Identity.Length==64,"bounded error response then recovery");});
  check("shared engine: readonly snapshot preserves original state",()=>{var s=State.New();var d=s.GetDay(new DateTime(2026,10,22));GridEngine.Ensure(s,d);string before=SharedEngine.Json(s);PhoneCodec.Snapshot(s,d.Date);ScheduleNotifications.Feed(s,d.Wake);Yes(SharedEngine.Json(s)==before,"view does not change facts or histories");});
  check("shared engine: day-scoped calculation preserves other days and Unicode",()=>{var s=State.New();var d=s.GetDay(new DateTime(2026,10,22));var other=s.GetDay(new DateTime(2026,10,23));other.Note="다음 날 메모 📝";GridEngine.Ensure(s,d);GridEngine.Build(s,d);Yes(Object.ReferenceEquals(other,s.Days[1])&&s.Days[1].Note=="다음 날 메모 📝","other day retained");d.Records.Add(new CellBlock{Id="unicode",Name="학습 📝",Category="학습",Start=d.Wake,Count=1});PhoneCodec.Snapshot(s,d.Date);Yes(d.Records[0].Name=="학습 📝","Unicode roundtrip");});
  check("shared engine: generic Preview profile survives C# storage",()=>{var result=SharedEngine.Call("previewSeed");var s=SharedEngine.Read<State>(result["state"]);var d=s.Days[0];Yes(s.PreviewConfig!=null&&s.Template.Count==0,"generic state retained");var plan=GridEngine.Build(s,d);Yes(plan.Blocks.Any(b=>b.Fixed),"fixed activity flag retained");var path=Path.Combine(dir,"shared-preview.json");new Store(path).Save(s);var loaded=new Store(path).Load();Yes(loaded.PreviewConfig.mode=="clock"&&SharedEngine.Json(loaded)==SharedEngine.Json(s),"profile roundtrip");});
 }
}}
